<?php declare(strict_types=1);require_once __DIR__.'/../config/auth.php';page_require(['ADMIN']);?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Monitor SaladCloud — Hache</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f7fb;color:#172033;font-family:Manrope,Arial,sans-serif}.wrap{width:min(1180px,94%);margin:0 auto;padding:78px 0 32px}.sub{color:#64748b;margin:6px 0 18px}.top{display:flex;align-items:end;justify-content:space-between;gap:16px;flex-wrap:wrap}.summary{display:flex;gap:8px;flex-wrap:wrap}.pill{padding:7px 10px;border-radius:99px;font-size:12px;font-weight:800;background:#fff;border:1px solid #e5eaf0}.pill.warn{background:#fffbeb;border-color:#f59e0b;color:#92400e}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(285px,1fr));gap:12px}.card{background:#fff;border:1px solid #e5eaf0;border-radius:16px;padding:16px;box-shadow:0 4px 16px #0f172a08}.card.stale{border-color:#f59e0b}.head{display:flex;gap:10px;align-items:start;justify-content:space-between}.name{font-weight:900;word-break:break-word}.gpu{font-size:13px;color:#64748b;margin-top:4px}.state{width:11px;height:11px;border-radius:50%;margin-top:4px}.green{background:#16a34a}.yellow{background:#f59e0b}.red{background:#dc2626}.metrics{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:15px}.metric{background:#f8fafc;border-radius:10px;padding:9px}.label{font-size:10px;text-transform:uppercase;color:#64748b;font-weight:800}.value{font-size:18px;font-weight:900;margin-top:2px}.small{font-size:12px;color:#64748b;margin-top:12px}.small.warn{color:#92400e;font-weight:800}.profit{margin-top:10px;padding:9px;border:1px solid #e2e8f0;border-radius:10px;font-size:12px;font-weight:750}.profit.healthy{background:#f0fdf4;color:#166534}.profit.watch{background:#fffbeb;color:#92400e}.profit.below_break_even{background:#fff1f2;color:#991b1b}.profit.unknown{background:#f8fafc;color:#475569}.empty{padding:28px;text-align:center;background:#fff;border-radius:16px;color:#64748b}.error{color:#991b1b;background:#fff1f2}.history{height:30px;display:flex;align-items:end;gap:2px;margin-top:12px}.bar{width:5px;min-height:2px;background:#2563eb;border-radius:3px 3px 0 0}@media(max-width:560px){.wrap{width:92%;padding-top:70px}.metrics{grid-template-columns:1fr 1fr}}.trial{background:#fff;border:1px solid #e5eaf0;border-radius:16px;padding:18px;margin-top:18px}.trial h2{font-size:18px;margin:0 0 8px}.trial-scroll{overflow-x:auto}.trial table{border-collapse:collapse;width:100%;font-size:12px;min-width:750px}.trial th,.trial td{border-bottom:1px solid #e5eaf0;text-align:left;padding:10px 8px;vertical-align:top}.trial th{color:#64748b}.trial small{display:block;color:#64748b;margin-top:4px}.trial .muted{color:#92400e}.trial .nums{text-align:right;white-space:nowrap}.trial .empty-row{padding:14px;color:#64748b}.pool-kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(145px,1fr));gap:10px;margin:12px 0}.pool-kpi{background:#f8fafc;border-radius:10px;padding:12px}.pool-kpi strong{display:block;font-size:19px;margin-top:5px}.pool-daily{display:flex;flex-wrap:wrap;gap:8px}.pool-day{padding:8px 10px;border:1px solid #e5eaf0;border-radius:10px;font-size:12px}.pool-day strong{display:block;margin-top:3px}.pool-warn{color:#92400e;font-size:12px;margin:6px 0}</style></head><body><main class="wrap"><div class="top"><div><h1>Monitor SaladCloud</h1><p><a href="/mineria-caja.php">Abrir caja de minería (privada) →</a></p><p class="sub">Proyecto prl-tests · snapshot seguro · actualización cada 5 minutos.</p><p class="sub">4070 Ti SUPER Low: aviso &lt;140 TH/s; posible pérdida ≤125 TH/s (media 15 min, referencias variables; no son ingresos medidos).</p></div><div class="summary" id="summary"></div></div><section class="trial" id="pool-prl"><h2>PRL acreditados por Kryptex</h2><p class="sub">Recompensas reales de la dirección PRL registrada. Son datos globales del pool, <strong>no atribuibles a una GPU individual</strong>; no equivalen a ventas en USD.</p><div id="pool-content">Sin lecturas del pool.</div></section><div id="content" class="empty">Cargando monitor…</div><section class="trial"><h2>Histórico de pruebas · últimos 7 días</h2><p class="sub">Registro permanente por grupo y GPU, con prioridad real (Lowest/Low/Medium). Las cifras TH/s × h son capacidad observada aproximada, <strong>no PRL confirmados ni ingresos</strong>. Los grupos con varias réplicas no tienen tasa individual atribuible.</p><div id="trial-history" class="trial-scroll"><p>Sin registros todavía.</p></div></section></main><script>
const c=document.getElementById('content'),s=document.getElementById('summary'),esc=v=>String(v??'—').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x])),n=v=>v==null?'—':Number(v).toLocaleString('es-MX',{maximumFractionDigits:2}),store='hache-salad-history-v1';let hasData=false;
function history(groups){let old=[];try{old=JSON.parse(localStorage.getItem(store)||'[]')}catch(e){}old.push({at:Date.now(),g:Object.fromEntries(groups.map(x=>[x.group,Number(x.metrics?.hashrate_ths||0)]))});old=old.filter(x=>x.at>Date.now()-86400000).slice(-288);try{localStorage.setItem(store,JSON.stringify(old))}catch(e){}return old}
function ageText(seconds){if(seconds==null)return 'antigüedad desconocida';if(seconds<90)return 'actualizado hace menos de 2 min';const min=Math.round(seconds/60);return 'datos de hace '+min+' min'}
function profitabilityTag(p,stale){if(!p?.applicable)return '';const level=stale?'unknown':p.level;const messages={healthy:'Media 15 min ≥140 TH/s · margen orientativo favorable',watch:'Media 15 min <140 TH/s · margen reducido (estimado)',below_break_even:'Media 15 min ≤125 TH/s · posible pérdida (estimado)',unknown:'Rentabilidad no evaluable con datos actuales'};return '<div class="profit '+(Object.hasOwn(messages,level)?level:'unknown')+'">'+esc(messages[level]||messages.unknown)+'</div>'}
function render(d){const groups=d.groups||[],h=history(groups),counts={green:0,yellow:0,red:0},partial=groups.filter(x=>x.stale).length;groups.forEach(x=>counts[x.health]=(counts[x.health]||0)+1);s.innerHTML=`<span class="pill">🟢 ${counts.green} estable</span><span class="pill">🟡 ${counts.yellow} revisar</span><span class="pill">🔴 ${counts.red} alerta</span><span class="pill ${d.stale||partial?'warn':''}">${esc(ageText(d.age_seconds))}${partial?' · '+partial+' grupo(s) sin refrescar':''}</span>`;c.className='grid';c.innerHTML=groups.map(x=>{const m=x.metrics||{},series=h.map(a=>a.g?.[x.group]||0),max=Math.max(1,...series);return `<article class="card ${x.stale?'stale':''}"><div class="head"><div><div class="name">${esc(x.display_name)}</div><div class="gpu">${esc(m.gpu||'Sin datos de SRBMiner')}</div></div><i class="state ${esc(x.health)}" title="${esc(x.health)}"></i></div><div class="metrics"><div class="metric"><div class="label">TH/s actual</div><div class="value">${n(m.hashrate_ths)}</div></div><div class="metric"><div class="label">Media 15 min</div><div class="value">${n(m.hashrate_15m_ths)}</div></div><div class="metric"><div class="label">Potencia / temp.</div><div class="value">${n(m.watts)} W · ${n(m.temperature_c)}°</div></div><div class="metric"><div class="label">Vent. / shares</div><div class="value">${n(m.fan_percent)}% · ${n(m.shares?.accepted)}</div></div></div><div class="history" aria-label="Histórico local de 24 horas">${series.map(v=>`<i class="bar" style="height:${Math.max(2,Math.round(v/max*30))}px"></i>`).join('')}</div>${profitabilityTag(m.profitability,x.stale)}<div class="small">Grupo: ${esc(x.state)} · Logs: ${esc(m.last_log_at||'sin lectura')}</div>${x.stale?'<div class="small warn">Último dato válido conservado; este grupo no pudo refrescarse.</div>':''}</article>`}).join('')||'<div class="empty">No hay Container Groups disponibles.</div>';hasData=true}
function renderPoolPRL(pool){
 const dest=document.getElementById('pool-content');
 if(!pool){dest.innerHTML='<p class="pool-warn">Sin lectura válida del pool todavía. El monitor seguirá registrando GPUs independientemente.</p>';return}
 const observed=Date.parse(pool.observed_at||'');const stale=!Number.isFinite(observed)||Date.now()-observed>1500000;
 const formatPrl=x=>Number(x??0).toLocaleString('es-MX',{minimumFractionDigits:3,maximumFractionDigits:6});
 const kpis=[['Confirmados',pool.confirmed_prl],['Pendientes',pool.unconfirmed_prl],['Saldo total',pool.total_prl],['Pagados acumulados',pool.paid_prl],['Recompensa 7 días',pool.reward_week_prl]];
 const rows=(pool.rewards_daily_utc||[]).slice(-7);
 dest.innerHTML=(stale?'<p class="pool-warn">La última consulta a Kryptex está desactualizada. Se conserva el último dato.</p>':'')+'<div class="pool-kpis">'+kpis.map(([label,value])=>'<div class="pool-kpi"><span>'+esc(label)+'</span><strong>'+formatPrl(value)+' PRL</strong></div>').join('')+'</div><p class="small">Dirección pública …'+esc(pool.wallet_suffix)+' · Actualización '+esc(new Date(observed).toLocaleString('es-MX',{timeZone:'America/Cancun'}))+' (Cancún)</p><p class="small">Recompensas por día (UTC; pueden ajustarse al confirmar):</p><div class="pool-daily">'+rows.map(r=>'<div class="pool-day">'+esc(r.date_utc)+'<strong>'+formatPrl(r.prl)+' PRL</strong></div>').join('')+'</div>';
}
function renderTrialHistory(data){
 const target=document.getElementById('trial-history');
 if(data?.error){target.textContent=data.error;return}
 const rows=data?.rows||[];
 if(!rows.length){target.innerHTML='<p class="empty-row">Todavía no hay mediciones históricas. Comenzarán con la próxima ejecución del monitor.</p>';return}
 target.innerHTML='<table><thead><tr><th>Fecha (Cancún)</th><th>Grupo / GPU</th><th>Prioridad</th><th class="nums">Réplicas máx.</th><th class="nums">Tiempo medido</th><th class="nums">TH/s promedio</th><th class="nums">TH/s × h</th></tr></thead><tbody>'+rows.map(r=>{
 const uncertain=r.ambiguous_samples>0; const measured=r.monitored_minutes>0;
 return '<tr><td>'+esc(r.date)+'</td><td><strong>'+esc(r.group)+'</strong><small>'+esc(r.gpu||'Sin identificar')+' · '+n(r.samples)+' muestras'+(uncertain?' · '+n(r.ambiguous_samples)+' ambiguas':'')+'</small></td><td>'+esc(r.priority||'—')+'</td><td class="nums">'+n(r.max_active)+'</td><td class="nums">'+(measured?n(r.monitored_minutes)+' min':'—')+'</td><td class="nums">'+(measured?n(r.average_ths):'—')+'</td><td class="nums">'+(measured?n(r.capacity_ths_hours):'—')+(uncertain?'<small class="muted">Réplicas múltiples sin atribuir</small>':'')+'</td></tr>';
 }).join('')+'</tbody></table>';
}
async function load(){try{const r=await fetch('/api/salad-monitor.php',{cache:'no-store'}),d=await r.json();if(!r.ok||!d.ok)throw Error(d.error||'No disponible');render(d);renderPoolPRL(d.prl_pool);renderTrialHistory(d.history)}catch(e){if(hasData){s.insertAdjacentHTML('beforeend','<span class="pill warn">No se pudo refrescar ahora; se mantienen los últimos datos.</span>')}else{c.className='empty error';c.textContent=e.message}}}
load();setInterval(load,300000)
</script></body></html>
